messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = -TRACK_LENGTH;
        const RACE_DURATION = 10; // seconds for a full race
        const RESET_DURATION = 2; // seconds to reset

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 300);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 15, 20);
        camera.lookAt(0, 0, -50);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(500, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(20, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, FINISH_LINE_Z);
        finishLine.receiveShadow = true;
        scene.add(finishLine);

        // Checkered pattern on finish line
        const checkGeo = new THREE.PlaneGeometry(20, 2);
        const checkMat = new THREE.MeshStandardMaterial({ color: 0x000000, roughness: 0.4 });
        const checks = [];
        for (let x = -9; x < 10; x += 2) {
            const check = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), checkMat);
            check.rotation.x = -Math.PI / 2;
            check.position.set(x, 0.02, FINISH_LINE_Z);
            check.receiveShadow = true;
            scene.add(check);
        }

        // --- Car Creation ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 0.8, 4.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.4 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.8;
            chassis.castShadow = true;
            chassis.receiveShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.7, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.1, metalness: 0.5 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.5;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2, 0.1, 0.5);
            const spoiler = new THREE.Mesh(spoilerGeo, chassisMat);
            spoiler.position.set(0, 1.5, 2);
            carGroup.add(spoiler);
            const spoilerLegGeo = new THREE.BoxGeometry(0.1, 0.3, 0.1);
            const leg1 = new THREE.Mesh(spoilerLegGeo, chassisMat);
            leg1.position.set(0.8, 1.3, 2);
            carGroup.add(leg1);
            const leg2 = new THREE.Mesh(spoilerLegGeo, chassisMat);
            leg2.position.set(-0.8, 1.3, 2);
            carGroup.add(leg2);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
            wheelGeo.rotateZ(Math.PI / 2);

            const wheelPositions = [
                { x: 1.1, y: 0.4, z: 1.5 },
                { x: -1.1, y: 0.4, z: 1.5 },
                { x: 1.1, y: 0.4, z: -1.5 },
                { x: -1.1, y: 0.4, z: -1.5 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000); // Bright Red
        const blueCar = createCar(0x0000ff); // Bright Blue

        // Initial positions
        redCar.position.set(3, 0, 0);
        blueCar.position.set(-3, 0, 0);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let raceTime = 0;
        let state = 'racing'; // 'racing' or 'resetting'

        // Helper for smooth easing
        function easeInOutCubic(t) {
            return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
        }

        function updateCars(dt) {
            if (state === 'racing') {
                raceTime += dt;
                if (raceTime >= RACE_DURATION) {
                    state = 'resetting';
                    raceTime = 0;
                }

                const t = raceTime / RACE_DURATION;

                // Blue Car Logic: Leads early, then slows down relative to red
                // Starts fast, accelerates slower later
                let blueProgress = t;
                if (t < 0.3) {
                    // Fast start
                    blueProgress = t * 1.5; 
                } else {
                    // Slows down
                    blueProgress = 0.45 + (t - 0.3) * 0.8;
                }
                blueProgress = Math.min(1, blueProgress);
                blueCar.position.z = FINISH_LINE_Z * blueProgress;

                // Red Car Logic: Slow start, accelerates hard in the middle, wins
                let redProgress = t;
                if (t < 0.2) {
                    // Slow start
                    redProgress = t * 0.8;
                } else if (t < 0.7) {
                    // Big acceleration
                    redProgress = 0.16 + (t - 0.2) * 1.4;
                } else {
                    // Cruising to finish
                    redProgress = 0.86 + (t - 0.7) * 0.55;
                }
                redProgress = Math.min(1, redProgress);
                redCar.position.z = FINISH_LINE_Z * redProgress;

            } else if (state === 'resetting') {
                raceTime += dt;
                if (raceTime >= RESET_DURATION) {
                    state = 'racing';
                    raceTime = 0;
                    redCar.position.z = 0;
                    blueCar.position.z = 0;
                } else {
                    // Reset animation (fade back to start)
                    const resetT = raceTime / RESET_DURATION;
                    const ease = easeInOutCubic(resetT);
                    redCar.position.z = FINISH_LINE_Z * (1 - ease);
                    blueCar.position.z = FINISH_LINE_Z * (1 - ease);
                }
            }
        }

        function updateCamera() {
            // Calculate midpoint between cars
            const midZ = (redCar.position.z + blueCar.position.z) / 2;
            const dist = Math.abs(redCar.position.z - blueCar.position.z);

            // Camera target position
            const targetZ = midZ - 15; // Behind the midpoint
            const targetX = 0;
            const targetY = 12;

            // Smoothly move camera
            camera.position.z += (targetZ - camera.position.z) * 0.05;
            camera.position.x += (targetX - camera.position.x) * 0.05;
            camera.position.y += (targetY - camera.position.y) * 0.05;

            // Look at midpoint slightly ahead
            camera.lookAt(0, 0, midZ - 30);
        }

        // --- Main Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const dt = clock.getDelta();

            updateCars(dt);
            updateCamera();

            renderer.render(scene, camera);
        }

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();
    </script>
</body>
</html>
```
